🐛 Describe the bug
We support tensor.__getitem__ and tensor[..] but graph break on torch.Tensor.__getitem__. Because we graph break here we do not get torch.compile test coverage for Tensor indexing opinfo.
import torch

@torch.compile()
def foo(x):
    return x.__getitem__([1, 2])

x = torch.rand([5, 5, 5])
# works
foo(x)

@torch.compile()
def foo(x):
    return torch.Tensor.__getitem__([1, 2])

# graph break
foo(x)

